const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const btn = $('#btn');
const btnRand = $('#btnRand');
const strip = $('#strip');
const names = $('#names');

const normEl = $('#norm');
const guessEl = $('#guess');
const previewEl = $('#preview');
const whyEl = $('#why');

// --- Unicode helpers ---
const COMBINING = /[\u0300-\u036f]/g;
function nfd(s){ return (s||'').normalize('NFD'); }
function nfc(s){ return (s||'').normalize('NFC'); }
function stripDiacritics(s){
  // remove combining marks (accents, breathings, iota subscript, diaeresis)
  return nfc(nfd(s).replace(COMBINING,''));
}
function stripPunctSpace(s){
  return (s||'').replace(/[\s··.,;:!?—–\-()\[\]{}"'“”‘’]/g,'');
}
function lowerGreek(s){
  // crude: JS lowercasing works fine for Greek
  return (s||'').toLowerCase();
}

// Add combining acute to the last vowel of the word (oxytone preview)
const VOWELS = new Set(['α','ε','η','ι','ο','υ','ω','ά','έ','ή','ί','ό','ύ','ώ']);
function addAcuteToLastVowel(word){
  const base = nfd(word);
  // find last Greek vowel letter (ignoring combining marks)
  let lastVowelIndex = -1;
  for(let i=0;i<base.length;i++){
    const ch = base[i];
    if(COMBINING.test(ch)) continue;
    if(VOWELS.has(ch)) lastVowelIndex = i;
  }
  if(lastVowelIndex === -1) return word;
  // insert combining acute after that vowel, but before any following combining marks
  let j = lastVowelIndex + 1;
  while(j < base.length && COMBINING.test(base[j])) j++;
  const out = base.slice(0,j) + '\u0301' + base.slice(j);
  return nfc(out);
}

function addAcuteToPenultVowel(word){
  // very rough: find last two vowel nuclei; accent the second-to-last
  const base = nfd(word);
  const vowelPositions = [];
  for(let i=0;i<base.length;i++){
    const ch = base[i];
    if(COMBINING.test(ch)) continue;
    if(VOWELS.has(ch)) vowelPositions.push(i);
  }
  if(vowelPositions.length < 2) return addAcuteToLastVowel(word);
  const target = vowelPositions[vowelPositions.length-2];
  let j = target + 1;
  while(j < base.length && COMBINING.test(base[j])) j++;
  return nfc(base.slice(0,j) + '\u0301' + base.slice(j));
}

function addAcuteToAntepenultVowel(word){
  const base = nfd(word);
  const vowelPositions = [];
  for(let i=0;i<base.length;i++){
    const ch = base[i];
    if(COMBINING.test(ch)) continue;
    if(VOWELS.has(ch)) vowelPositions.push(i);
  }
  if(vowelPositions.length < 3) return addAcuteToPenultVowel(word);
  const target = vowelPositions[vowelPositions.length-3];
  let j = target + 1;
  while(j < base.length && COMBINING.test(base[j])) j++;
  return nfc(base.slice(0,j) + '\u0301' + base.slice(j));
}

// --- Heuristic engine ---
const exceptions = {
  // oxytone exceptions
  'τρωκμος': {type:'oxytone', note:'Exception in the passage: Τρωκμός is said to be oxytone.'},
  'ατμος': {type:'oxytone', note:'Noted exception: ἀτμός is oxytone.'},
  'βρυσμος': {type:'oxytone', note:'Named in the passage: Βρυσμός (a king) is oxytone.'},
  'κρουσμος': {type:'oxytone', note:'Contrasted with κόσμος: κρουσμός is oxytone.'},
  // barytone exceptions
  'κοσμος': {type:'barytone', note:'Explicit: κόσμος is barytone.'},
  'ορμος': {type:'barytone', note:'Explicit: ὅρμος is barytone.'},
  'αλμος': {type:'barytone', note:'Proper name Ἄλμος is barytone (also an appellative ὅλμος is barytone).'},
  'ολμος': {type:'barytone', note:'Proper name Ὅλμος and the appellative ὅλμος are barytone.'},
  // proparoxytone compound
  'συνδεσμος': {type:'proparoxytone', note:'Explicit: σύνδεσμος is proparoxytone as a compound.'}
};

function analyze(raw){
  const original = raw || '';
  let s = stripPunctSpace(original);
  const hadAnything = s.length>0;

  // normalize accents if requested
  if(strip.checked) s = stripDiacritics(s);
  s = lowerGreek(s);

  // also keep a display form (without stripping case too aggressively)
  const displayNorm = hadAnything ? s : '';

  // only analyze last token-ish; but we already stripped spaces/punct.
  const key = s;

  const result = {
    norm: displayNorm || '—',
    ok: false,
    kind: '—',
    preview: '—',
    why: ''
  };

  if(!hadAnything){
    result.why = 'Type something ending in -μος.';
    return result;
  }

  if(!key.endsWith('μος')){
    result.kind = 'Not in -μος';
    result.preview = nfc(original);
    result.why = 'This toy only plays with words ending in -μος (as in the passage).';
    return result;
  }

  // exception table first
  if(exceptions[key]){
    const ex = exceptions[key];
    result.ok = true;
    result.kind = ex.type;
    result.why = ex.note;
    result.preview = accentPreview(key, ex.type);
    return result;
  }

  // detect cluster before μ
  const beforeMu = key.slice(0, -2); // remove 'ος' leaving ...μ
  const preMuChar = beforeMu.length ? beforeMu[beforeMu.length-1] : '';

  // crude compound hint: starts with συν-
  const isSyn = key.startsWith('συν');
  if(isSyn){
    result.ok = true;
    result.kind = 'proparoxytone?';
    result.preview = accentPreview(key, 'proparoxytone');
    result.why = 'Looks like a σύν- compound; the passage notes σύνδεσμος as proparoxytone because it is a compound. (Heuristic: compounds may pull accent back.)';
    return result;
  }

  // rules from passage
  if(preMuChar === 'κ'){
    result.ok = true;
    // Herodian: usually barytone
    result.kind = names.checked ? 'barytone (name?)' : 'barytone';
    result.preview = accentPreview(key, 'barytone');
    result.why = 'Pattern …κμος: Herodian says these are rare and tend to be barytone (Λάκμος, Δέκμος), with a famous exception Τρωκμός.';
    return result;
  }
  if(preMuChar === 'τ'){
    result.ok = true;
    result.kind = 'barytone';
    result.preview = accentPreview(key, 'barytone');
    result.why = 'Pattern …τμος: Herodian says these tend to be barytone (πότμος, Πάτμος, Λάτμος), with exception ἀτμός.';
    return result;
  }
  if(preMuChar === 'σ'){
    // special: if penult is just -οσ- (…οσμος) then κόσμος barytone; we already caught κόσμος.
    const endsWithOSMOS = key.endsWith('οσμος');
    result.ok = true;
    if(endsWithOSMOS){
      result.kind = 'barytone (likely)';
      result.preview = accentPreview(key, 'barytone');
      result.why = 'Pattern …οσμος: the passage warns “not having only ο” in the penult; κόσμος is barytone. Your form looks like …οσμος, so barytone is a decent guess.';
    } else {
      // appellatives often oxytone; but proper names may be barytone
      if(names.checked){
        result.kind = 'barytone (proper-name bias)';
        result.preview = accentPreview(key, 'barytone');
        result.why = 'Pattern …σμος: Herodian says simple appellatives are often oxytone (δεσμός etc.), but he explicitly excludes barytone proper names (e.g. Κάσμος). You checked “proper name”, so we bias barytone.';
      } else {
        result.kind = 'oxytone';
        result.preview = accentPreview(key, 'oxytone');
        result.why = 'Pattern …σμος: Herodian says simple appellatives are often oxytone (ῥυσμός, δεσμός, θεσμός…).';
      }
    }
    return result;
  }
  if(preMuChar === 'λ'){
    result.ok = true;
    if(names.checked){
      result.kind = 'barytone (proper-name bias)';
      result.preview = accentPreview(key, 'barytone');
      result.why = 'Pattern …λμος: appellatives tend to be oxytone (ὀφθαλμός, ψαλμός), but some proper names are barytone (Ἄλμος, Ὅλμος). With “proper name” checked, we bias barytone.';
    } else {
      result.kind = 'oxytone';
      result.preview = accentPreview(key, 'oxytone');
      result.why = 'Pattern …λμος: Herodian says appellatives with penult ending in λ are oxytone (ὀφθαλμός, ψαλμός, παλμός…).';
    }
    return result;
  }
  if(preMuChar === 'ρ'){
    result.ok = true;
    // passage: appellative/adjectival oxytone, but ὅρμος barytone (already caught)
    if(names.checked){
      result.kind = 'proper name (uncertain)';
      result.preview = accentPreview(key, 'barytone');
      result.why = 'Pattern …ρμος: Herodian says appellatives/adjectives are often oxytone (κορμός, θερμός), but some proper names exist. With “proper name” checked, we avoid overconfident oxytone and show a conservative barytone preview.';
    } else {
      result.kind = 'oxytone';
      result.preview = accentPreview(key, 'oxytone');
      result.why = 'Pattern …ρμος: Herodian says appellative/adjectival forms are oxytone (κορμός, φορμός, θερμός), with exception ὅρμος.';
    }
    return result;
  }

  // fallback
  result.ok = true;
  result.kind = 'unknown (fallback)';
  result.preview = accentPreview(key, 'oxytone');
  result.why = 'No specific cluster rule from the passage matched (κ/τ/σ/λ/ρ before μ). As a playful fallback, we show an oxytone preview.';
  return result;
}

function accentPreview(word, kind){
  // word is expected unaccented-ish; we add combining acute for preview.
  if(kind === 'oxytone') return addAcuteToLastVowel(word);
  if(kind === 'proparoxytone') return addAcuteToAntepenultVowel(word);
  if(kind === 'paroxytone') return addAcuteToPenultVowel(word);
  // barytone: show unaccented (or keep as-is)
  return word;
}

function render(){
  const r = analyze(inp.value);
  normEl.textContent = r.norm;

  let label = r.kind;
  if(r.kind === 'oxytone') label = 'Oxytone (accent on last syllable)';
  if(r.kind === 'barytone') label = 'Barytone tendency (not oxytone)';
  if(r.kind === 'proparoxytone') label = 'Proparoxytone (accent on antepenult)';

  guessEl.innerHTML = `<span class="badge">${escapeHtml(label)}</span>`;
  previewEl.textContent = r.preview;
  whyEl.textContent = r.why;
}

function escapeHtml(s){
  return (s+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

const examples = [
  'δεσμος','θεσμος','χρησμος','σπασμος','κοσμος','κρουσμος','συνδεσμος',
  'Λακμος','Δεκμος','Τρωκμος','ποτμος','Πατμος','Λατμος','ατμος',
  'οφθαλμος','ψαλμος','παλμος','κορμος','θερμος','ορμος','Βρυσμος'
];

btn.addEventListener('click', render);
inp.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
strip.addEventListener('change', render);
names.addEventListener('change', render);

btnRand.addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  inp.value = ex;
  render();
});

// initial
inp.value = 'δεσμος';
render();

