  // detect cluster before μ
  const beforeMu = key.slice(0, -2); // remove 'ος' leaving ...μ
  const preMuChar = beforeMu.length ? beforeMu[beforeMu.length-1] : '';

  // crude compound hint: starts with συν-
  const isSyn = key.startsWith('συν');
  if(isSyn){
    result.ok = true;
    result.kind = 'proparoxytone?';
    result.preview = accentPreview(key, 'proparoxytone');
    result.why = 'Looks like a σύν- compound; the passage notes σύνδεσμος as proparoxytone because it is a compound. (Heuristic: compounds may pull accent back.)';
    return result;
  }

  // rules from passage
  if(preMuChar === 'κ'){
    result.ok = true;
    // Herodian: usually barytone
    result.kind = names.checked ? 'barytone (name?)' : 'barytone';
    result.preview = accentPreview(key, 'barytone');
    result.why = 'Pattern …κμος: Herodian says these are rare and tend to be barytone (Λάκμος, Δέκμος), with a famous exception Τρωκμός.';
    return result;
  }
  if(preMuChar === 'τ'){
    result.ok = true;
    result.kind = 'barytone';
    result.preview = accentPreview(key, 'barytone');
    result.why = 'Pattern …τμος: Herodian says these tend to be barytone (πότμος, Πάτμος, Λάτμος), with exception ἀτμός.';
    return result;
  }
  if(preMuChar === 'σ'){
    // special: if penult is just -οσ- (…οσμος) then κόσμος barytone; we already caught κόσμος.
    const endsWithOSMOS = key.endsWith('οσμος');
    result.ok = true;
    if(endsWithOSMOS){
      result.kind = 'barytone (likely)';
      result.preview = accentPreview(key, 'barytone');
      result.why = 'Pattern …οσμος: the passage warns “not having only ο” in the penult; κόσμος is barytone. Your form looks like …οσμος, so barytone is a decent guess.';
    } else {
      // appellatives often oxytone; but proper names may be barytone
      if(names.checked){
        result.kind = 'barytone (proper-name bias)';
        result.preview = accentPreview(key, 'barytone');
        result.why = 'Pattern …σμος: Herodian says simple appellatives are often oxytone (δεσμός etc.), but he explicitly excludes barytone proper names (e.g. Κάσμος). You checked “proper name”, so we bias barytone.';
      } else {
        result.kind = 'oxytone';
        result.preview = accentPreview(key, 'oxytone');
        result.why = 'Pattern …σμος: Herodian says simple appellatives are often oxytone (ῥυσμός, δεσμός, θεσμός…).';
      }
    }
    return result;
  }
  if(preMuChar === 'λ'){
    result.ok = true;
    if(names.checked){
      result.kind = 'barytone (proper-name bias)';
      result.preview = accentPreview(key, 'barytone');
      result.why = 'Pattern …λμος: appellatives tend to be oxytone (ὀφθαλμός, ψαλμός), but some proper names are barytone (Ἄλμος, Ὅλμος). With “proper name” checked, we bias barytone.';
    } else {
      result.kind = 'oxytone';
      result.preview = accentPreview(key, 'oxytone');
      result.why = 'Pattern …λμος: Herodian says appellatives with penult ending in λ are oxytone (ὀφθαλμός, ψαλμός, παλμός…).';
    }
    return result;
  }
  if(preMuChar === 'ρ'){
    result.ok = true;
    // passage: appellative/adjectival oxytone, but ὅρμος barytone (already caught)
    if(names.checked){
      result.kind = 'proper name (uncertain)';
      result.preview = accentPreview(key, 'barytone');
      result.why = 'Pattern …ρμος: Herodian says appellatives/adjectives are often oxytone (κορμός, θερμός), but some proper names exist. With “proper name” checked, we avoid overconfident oxytone and show a conservative barytone preview.';
    } else {
      result.kind = 'oxytone';
      result.preview = accentPreview(key, 'oxytone');
      result.why = 'Pattern …ρμος: Herodian says appellative/adjectival forms are oxytone (κορμός, φορμός, θερμός), with exception ὅρμος.';
    }
    return result;
  }

  // fallback
  result.ok = true;
  result.kind = 'unknown (fallback)';
  result.preview = accentPreview(key, 'oxytone');
  result.why = 'No specific cluster rule from the passage matched (κ/τ/σ/λ/ρ before μ). As a playful fallback, we show an oxytone preview.';
  return result;
}

function accentPreview(word, kind){
  // word is expected unaccented-ish; we add combining acute for preview.
  if(kind === 'oxytone') return addAcuteToLastVowel(word);
  if(kind === 'proparoxytone') return addAcuteToAntepenultVowel(word);
  if(kind === 'paroxytone') return addAcuteToPenultVowel(word);
  // barytone: show unaccented (or keep as-is)
  return word;
}

function render(){
  const r = analyze(inp.value);
  normEl.textContent = r.norm;

  let label = r.kind;
  if(r.kind === 'oxytone') label = 'Oxytone (accent on last syllable)';
  if(r.kind === 'barytone') label = 'Barytone tendency (not oxytone)';
  if(r.kind === 'proparoxytone') label = 'Proparoxytone (accent on antepenult)';

  guessEl.innerHTML = `<span class="badge">${escapeHtml(label)}</span>`;
  previewEl.textContent = r.preview;
  whyEl.textContent = r.why;
}

function escapeHtml(s){
  return (s+'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

